create or replace function app_private.teaching_reassignment_command(p_name text,p_input jsonb,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare actor uuid:=app_private.require_actor();ctx jsonb;p app_private.tutor_reassignments%rowtype;o app_private.occurrences%rowtype;old_tutor app_private.tutors%rowtype;new_tutor app_private.tutors%rowtype;fee finance_private.tutor_fee_agreements%rowtype;assignment app_private.tutor_assignments%rowtype;new_fee bigint;old_amount bigint;expires timestamptz;terms jsonb;context jsonb;hash text;terms_row record;seat record;participant uuid;kind text;view text;participants jsonb;blockers text[];all_accepted boolean;result jsonb;new_assignment uuid;new_agreement uuid;obligation uuid;new_availability integer;new_terms jsonb;old_terms jsonb;event_id uuid;begin
 if p_name='propose_tutor_reassignment' then perform app_private.require_role(actor,'admin');o.id:=(p_input->>'occurrence_id')::uuid;new_tutor.id:=(p_input->>'new_tutor_id')::uuid;
 else select * into p from app_private.tutor_reassignments where id=(p_input->>'proposal_id')::uuid;if p.id is null then raise exception 'NOT_FOUND';end if;o.id:=p.occurrence_id;new_tutor.id:=p.new_tutor_id;
  if p_name in('approve_tutor_reassignment','commit_tutor_reassignment') then perform app_private.require_role(actor,'admin');
  elsif p_name='decline_tutor_reassignment' and app_private.has_role(actor,'admin') then view:='admin';
  else select x.participant_id,x.kind into participant,kind from(select c.learner_id participant_id,'learner'::text kind,c.terms_hash from app_private.tutor_reassignment_customer_terms c where c.proposal_id=p.id and app_private.booking_can_access(actor,c.learner_id) union all select t.tutor_id,t.participant_kind,t.terms_hash from finance_private.tutor_reassignment_tutor_terms t join app_private.tutors teacher on teacher.id=t.tutor_id where t.proposal_id=p.id and teacher.account_id=actor and app_private.has_role(actor,'tutor'))x where(p_name='decline_tutor_reassignment' or x.terms_hash=p_input->>'terms_hash') order by x.kind,x.participant_id limit 1;if participant is null then raise exception 'FORBIDDEN';end if;end if;
 end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;perform app_private.teaching_lock_occurrences(array[o.id],array[new_tutor.id]);select * into o from app_private.occurrences where id=o.id for update;if o.id is null then raise exception 'NOT_FOUND';end if;
 if p_name='propose_tutor_reassignment' then
  if(p_input->>'expected_version')::integer is distinct from o.version then raise exception 'VERSION_CONFLICT';end if;if o.state not in('forming','confirmed') or o.start_at<=now() or o.tutor_id=new_tutor.id then raise exception 'STATE_CONFLICT';end if;
  select * into old_tutor from app_private.tutors where id=o.tutor_id;select * into new_tutor from app_private.tutors where id=new_tutor.id;select * into fee from finance_private.tutor_fee_agreements where id=o.current_fee_agreement_id;select * into assignment from app_private.tutor_assignments where occurrence_id=o.id and active;
  if new_tutor.id is null or new_tutor.approved_profile_version_id is null or old_tutor.approved_profile_version_id is null or assignment.id is null then raise exception 'STATE_CONFLICT';end if;perform app_private.require_role(old_tutor.account_id,'tutor');perform app_private.require_role(new_tutor.account_id,'tutor');if not app_private.payment_verified_account(new_tutor.account_id) or not app_private.payment_verified_account(old_tutor.account_id) then raise exception 'FORBIDDEN';end if;
  if not exists(select 1 from app_private.tutor_profile_versions profile join app_private.offers offer on offer.id=o.offer_id where profile.id=new_tutor.approved_profile_version_id and offer.subject_id=any(profile.subject_ids)) then raise exception 'STATE_CONFLICT';end if;
  new_fee:=(p_input->>'new_fee_minor')::bigint;old_amount:=(p_input->>'old_tutor_compensation_minor')::bigint;expires:=(p_input->>'expires_at')::timestamptz;
  if new_fee is null or old_amount is null or old_amount<0 or old_amount>coalesce(fee.fee_minor,0) or expires is null or not isfinite(expires) or expires<=now() or expires>o.start_at or p_input->>'reason' is null or length(btrim(p_input->>'reason')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
  perform app_private.assert_catalog_publication(app_private.catalog_environment(),price.environment_scope,price.is_synthetic) from app_private.pricing_versions price where price.id=o.pricing_version_id;perform app_private.assert_exact_tutor_fee(o.pricing_version_id,o.target_tier,new_fee,'EGP',o.duration_minutes);perform app_private.booking_assert_schedule(new_tutor.id,o.start_at,o.end_at,o.id);if fee.id is not null then perform app_private.require_role(fee.approved_by,'admin');end if;
  insert into app_private.tutor_reassignments(occurrence_id,original_assignment_id,old_tutor_id,new_tutor_id,old_profile_id,new_profile_id,base_occurrence_version,start_at,end_at,roster_hash,expires_at,created_by,reason) values(o.id,assignment.id,old_tutor.id,new_tutor.id,old_tutor.approved_profile_version_id,new_tutor.approved_profile_version_id,o.version,o.start_at,o.end_at,app_private.booking_roster_fingerprint(o.id),expires,actor,p_input->>'reason') returning * into p;
  context:=jsonb_build_object('proposal_id',p.id,'occurrence_id',o.id,'base_occurrence_version',o.version,'old_tutor_id',old_tutor.id,'new_tutor_id',new_tutor.id,'start_at',o.start_at,'end_at',o.end_at,'expires_at',expires);
  for seat in select e.learner_id,e.id,q.id quote_id,q.policy_version_id,q.customer_price_minor from app_private.enrollments e join app_private.quotes q on q.id=e.current_quote_id where e.occurrence_id=o.id and(e.state='confirmed' or(e.state='held' and e.hold_expires_at>now())) order by e.learner_id loop
   terms:=jsonb_build_object('kind','tutor_reassignment','learner_id',seat.learner_id,'enrollment_id',seat.id,'source_quote_id',seat.quote_id,'policy_version_id',seat.policy_version_id,'customer_price_minor',seat.customer_price_minor,'currency','EGP','charges_unchanged',true);insert into app_private.tutor_reassignment_customer_terms(proposal_id,learner_id,terms,terms_hash) values(p.id,seat.learner_id,terms,app_private.catalog_hash(context||jsonb_build_object('terms',terms)));
  end loop;
  terms:=jsonb_build_object('tutor_id',old_tutor.id,'role','previous','amount_kind','release_compensation','amount_minor',old_amount,'reference_fee_minor',fee.fee_minor,'currency','EGP','duration_minutes',o.duration_minutes,'source_fee_agreement_id',fee.id,'compensation_policy_version_id',o.pricing_version_id);insert into finance_private.tutor_reassignment_tutor_terms values(p.id,old_tutor.id,'previous_tutor',terms,app_private.catalog_hash(context||jsonb_build_object('terms',terms)));
  terms:=jsonb_build_object('tutor_id',new_tutor.id,'role','replacement','amount_kind','teaching_fee','amount_minor',new_fee,'reference_fee_minor',null,'currency','EGP','duration_minutes',o.duration_minutes,'source_fee_agreement_id',null,'compensation_policy_version_id',o.pricing_version_id);insert into finance_private.tutor_reassignment_tutor_terms values(p.id,new_tutor.id,'replacement_tutor',terms,app_private.catalog_hash(context||jsonb_build_object('terms',terms)));
  result:=app_private.booking_finish(ctx,p.id,1,jsonb_build_object('proposal_id',p.id,'state','proposed'),'tutor_reassignment_proposed',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));perform set_config('response.status','201',true);return result;
 end if;
 select * into p from app_private.tutor_reassignments where id=p.id for update;if(p_input->>'expected_version')::integer is distinct from p.version then raise exception 'VERSION_CONFLICT';end if;if p.state not in('proposed','accepted','approved') or p.expires_at<=now() then raise exception 'STATE_CONFLICT';end if;
 if p_name='decline_tutor_reassignment' then if p_input->>'reason' is null or length(btrim(p_input->>'reason')) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;update app_private.tutor_reassignments set state='declined',version=version+1 where id=p.id;return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state','declined'),'tutor_reassignment_declined',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));end if;
 blockers:=app_private.teaching_reassignment_blockers(p.id);if cardinality(blockers)>0 then if 'ROLE_REVOKED'=any(blockers) then raise exception 'FORBIDDEN';elsif 'AVAILABILITY_CONFLICT'=any(blockers) then raise exception 'SCHEDULE_CONFLICT';else raise exception 'VERSION_CONFLICT';end if;end if;
 if p_name='accept_tutor_reassignment' then
  if kind='learner' then perform app_private.assert_learner_scope(actor,participant,'booking');else perform app_private.require_role(actor,'tutor');end if;
  insert into app_private.tutor_reassignment_acceptances(proposal_id,participant_kind,participant_id,actor_account_id,terms_hash) values(p.id,kind,participant,actor,p_input->>'terms_hash') on conflict(proposal_id,participant_kind,participant_id) do nothing;
  participants:=app_private.teaching_reassignment_participants(p.id);all_accepted:=not exists(select 1 from jsonb_array_elements(participants)x where not(x->>'current')::boolean);update app_private.tutor_reassignments set state=case when all_accepted then 'accepted' else 'proposed' end,version=version+1 where id=p.id;
  return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state',case when all_accepted then 'accepted' else 'proposed' end),'tutor_reassignment_accepted',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));
 end if;
 participants:=app_private.teaching_reassignment_participants(p.id);if exists(select 1 from jsonb_array_elements(participants)x where not(x->>'current')::boolean) then raise exception 'CONSENT_REQUIRED';end if;
 perform app_private.require_role(p.created_by,'admin');for terms_row in select * from app_private.tutor_reassignment_acceptances where proposal_id=p.id order by participant_kind,participant_id loop if terms_row.participant_kind='learner' then perform app_private.assert_learner_scope(terms_row.actor_account_id,terms_row.participant_id,'booking');else perform app_private.require_role(terms_row.actor_account_id,'tutor');end if;end loop;
 if p_name='approve_tutor_reassignment' then if p.state<>'accepted' or p_input->>'terms_hash' is distinct from app_private.teaching_reassignment_hash(p.id) then raise exception 'STATE_CONFLICT';end if;update app_private.tutor_reassignments set state='approved',approved_by=actor,approved_at=now(),version=version+1 where id=p.id;return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state','approved'),'tutor_reassignment_approved',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));end if;
 if p_name<>'commit_tutor_reassignment' or p.state<>'approved' then raise exception 'STATE_CONFLICT';end if;perform app_private.require_role(p.approved_by,'admin');select * into fee from finance_private.tutor_fee_agreements where id=o.current_fee_agreement_id;if fee.id is not null then perform app_private.require_role(fee.approved_by,'admin');end if;
 select t.terms into new_terms from finance_private.tutor_reassignment_tutor_terms t where t.proposal_id=p.id and t.participant_kind='replacement_tutor';select t.terms into old_terms from finance_private.tutor_reassignment_tutor_terms t where t.proposal_id=p.id and t.participant_kind='previous_tutor';perform app_private.assert_catalog_publication(app_private.catalog_environment(),price.environment_scope,price.is_synthetic) from app_private.pricing_versions price where price.id=o.pricing_version_id;perform app_private.assert_exact_tutor_fee(o.pricing_version_id,o.target_tier,(new_terms->>'amount_minor')::bigint,'EGP',o.duration_minutes);new_availability:=app_private.booking_assert_schedule(p.new_tutor_id,o.start_at,o.end_at,o.id);
 insert into finance_private.tutor_fee_agreements(occurrence_id,tutor_id,pricing_version_id,target_tier,purpose,fee_minor,currency,duration_minutes,base_occurrence_version,approved_by) values(o.id,p.new_tutor_id,o.pricing_version_id,o.target_tier,'amendment',(new_terms->>'amount_minor')::bigint,'EGP',o.duration_minutes,o.version,p.approved_by) returning id into new_agreement;
 update app_private.tutor_assignments set active=false where id=p.original_assignment_id;insert into app_private.tutor_assignments(occurrence_id,tutor_id,version) values(o.id,p.new_tutor_id,(select max(version)+1 from app_private.tutor_assignments where occurrence_id=o.id)) returning id into new_assignment;
 update app_private.tutor_reservations set tutor_id=p.new_tutor_id where occurrence_id=o.id;update app_private.occurrences set tutor_id=p.new_tutor_id,current_fee_agreement_id=new_agreement,availability_version=new_availability,version=version+1,meeting_status='pending',updated_at=now() where id=o.id returning * into o;
 insert into finance_private.tutor_reassignment_obligations(proposal_id,occurrence_id,original_assignment_id,tutor_id,base_fee_agreement_id,amount_minor,command_id) values(p.id,o.id,p.original_assignment_id,p.old_tutor_id,(old_terms->>'source_fee_agreement_id')::uuid,(old_terms->>'amount_minor')::bigint,(ctx->>'command_id')::uuid) returning id into obligation;
 insert into app_private.tutor_reassignment_outcomes(proposal_id,assignment_id,fee_agreement_id,obligation_id,command_id) values(p.id,new_assignment,new_agreement,obligation,(ctx->>'command_id')::uuid);update app_private.tutor_reassignments set state='committed',committed_at=now(),version=version+1 where id=p.id;
 update app_private.calendar_events set meeting_generation=meeting_generation+1,conference_request_id=gen_random_uuid(),synced_occurrence_version=null,meeting_status='pending',join_url=null,updated_at=now() where occurrence_id=o.id;
 event_id:=gen_random_uuid();perform app_private.enqueue_event(event_id,'tutor_assignment_changed',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'old_tutor_id',p.old_tutor_id,'new_tutor_id',p.new_tutor_id,'assignment_id',new_assignment),'calendar.sync');perform app_private.enqueue_event(event_id,'tutor_assignment_changed',o.id,jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'old_tutor_id',p.old_tutor_id,'new_tutor_id',p.new_tutor_id,'assignment_id',new_assignment),'notifications.route');
 return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state','committed','assignment_id',new_assignment,'fee_agreement_id',new_agreement),'tutor_reassignment_committed',jsonb_build_object('occurrence_id',o.id,'occurrence_version',o.version,'proposal_id',p.id));
exception when invalid_text_representation or datetime_field_overflow then raise exception 'VALIDATION_ERROR';
end $$;
